    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
pairs=[]
for p in range(1,5):
    A=np.array(G[f'Demo pair {p} input']); O=np.array(G[f'Demo pair {p} output'])
    cols=[]; Cs=[]
    for c in [0,5,10,15]:
        s=A[:,c:c+4]; v=int(np.unique(s[s!=0])[0])
        cols.append(s); Cs.append(v)
    pairs.append((A,O,cols,Cs))
for idx,(A,O,cols,Cs) in enumerate(pairs):
    print('=== pair',idx+1)
    for k,s in enumerate(cols):
        print('strip',k,Cs[k])
        for r in s: print('  ',''.join('#' if v else '.' for v in r))
    print('OUT:')
    for r in O.tolist(): print('  ',r)

