G=load()
pairs=[]
for p in range(1,5):
    A=np.array(G[f'Demo pair {p} input']); O=np.array(G[f'Demo pair {p} output'])
    cols=[]; Cs=[]
    for c0 in [0,5,10,15]:
        s=A[:,c0:c0+4]; vals,cnt=np.unique(s,sreturn=True)
